 for patch in select value from jsonb_array_elements($questions$[{"before_md5":"cde6b31af809f6cd0a7487a69803b089","after":{"id":"f-16","test_key":"final","unit_id":"flow-no-pitch","prompt":{"en":"A customer has finished buying and wants to keep chatting normally. What is appropriate?","mk":"Клиент завршил со купување и сака да продолжи нормално да разговара. Што е соодветно?"},"options":[{"id":"a","en":"Stop replying because there is no new purchase.","mk":"Престани да одговараш затоа што нема ново купување."},{"id":"b","en":"Continue the conversation, or end warmly when appropriate.","mk":"Продолжи го разговорот или заврши топло кога е соодветно."},{"id":"c","en":"Require another purchase before talking.","mk":"Побарај ново купување пред да разговараш."},{"id":"d","en":"Repeat the declined offer immediately.","mk":"Веднаш повтори ја одбиената понуда."}],"correct":"b","source_anchor":"Wrap up warmly or continue chatting as normal.","explanation":{"en":"Normal conversation or a warm ending keeps the interaction positive.","mk":"Нормален разговор или топол крај ја задржува комуникацијата позитивна."}}},{"before_md5":"833de8e933ecd5d49dd00b918bc14702","after":{"id":"f-17","test_key":"final","unit_id":"rapport-practice","prompt":{"en":"A fan tells you about a stressful workday. What shows that you are listening?","mk":"Фан ти раскажува за стресен работен ден. Што покажува дека го слушаш?"},"options":[{"id":"a","en":"Ask a relevant follow-up about what they shared.","mk":"Постави соодветно дополнително прашање за она што го споделил."},{"id":"b","en":"Change to an unrelated sales message.","mk":"Премини на неповрзана продажна порака."},{"id":"c","en":"Repeat the question they just answered.","mk":"Повтори го прашањето на кое штотуку одговорил."},{"id":"d","en":"Ignore the detail and end the chat.","mk":"Игнорирај го деталот и заврши го разговорот."}],"correct":"a","source_anchor":"Instead of changing topics immediately, show interest in the answer.","explanation":{"en":"Show interest in the answer rather than immediately changing the topic.","mk":"Покажи интерес за одговорот наместо веднаш да ја менуваш темата."}}},{"before_md5":"ef791dd817f48ff85abb55c0295fda81","after":{"id":"f-18","test_key":"final","unit_id":"rapport-practice","prompt":{"en":"A promise could make an offer sound better, but you cannot be sure the creator can fulfill it. What should you do?","mk":"Ветување би ја направило понудата попривлечна, но не си сигурен дека креаторката може да го исполни. Што треба да направиш?"},"options":[{"id":"a","en":"Promise it now and check after payment.","mk":"Вети го сега и провери по плаќањето."},{"id":"b","en":"Use it because the fan wants to hear it.","mk":"Користи го затоа што фанот сака да го слушне."},{"id":"c","en":"Promise the same thing to every customer.","mk":"Вети го истото на секој клиент."},{"id":"d","en":"Avoid making a promise you cannot keep.","mk":"Избегни ветување што не можеш да го исполниш."}],"correct":"d","source_anchor":"Do not pretend to have personal experiences or make commitments on behalf of the creator that you cannot fulfill.","explanation":{"en":"Do not make commitments for the creator that you cannot fulfill.","mk":"Не преземај обврски за креаторката што не можеш да ги исполниш."}}},{"before_md5":"c559aa5240c0c1e52e9a495f31aa24b5","after":{"id":"f-19","test_key":"final","unit_id":"daily-offers","prompt":{"en":"A fan wants a custom video tomorrow. The creator has not confirmed the deadline. What should you do?","mk":"Фан сака видео по нарачка за утре. Креаторката не го потврдила рокот. Што треба да направиш?"},"options":[{"id":"a","en":"Promise tomorrow because the fan is ready to pay.","mk":"Вети за утре затоа што фанот е подготвен да плати."},{"id":"b","en":"Choose a deadline based on a different creator.","mk":"Одбери рок според друга креаторка."},{"id":"c","en":"Get the creator’s approval before promising delivery.","mk":"Добиј одобрение од креаторката пред да ветиш испорака."},{"id":"d","en":"Promise the date but leave it out of the notes.","mk":"Вети го датумот, но не го запишувај во белешките."}],"correct":"c","source_anchor":"Never promise a custom video, delivery date, or feature without the creator's authorization.","explanation":{"en":"Never promise custom content or a delivery date without the creator’s authorization.","mk":"Никогаш не ветувај содржина по нарачка или датум на испорака без одобрение од креаторката."}}},{"before_md5":"06e230966d18851f57627936cc013fdf","after":{"id":"f-20","test_key":"final","unit_id":"daily-offers","prompt":{"en":"A customer asks for a price. You remember an example from training. What should determine the actual price?","mk":"Клиент прашува за цена. Се сеќаваш на пример од обуката. Што треба да ја одреди вистинската цена?"},"options":[{"id":"a","en":"The example price, regardless of the creator.","mk":"Примерната цена, без оглед на креаторката."},{"id":"b","en":"The creator’s agreed pricing for that content.","mk":"Договорената цена на креаторката за таа содржина."},{"id":"c","en":"An unapproved discount you make up.","mk":"Неодобрен попуст што ќе го измислиш."},{"id":"d","en":"Whatever price the fan requests.","mk":"Која било цена што ја бара фанот."}],"correct":"b","source_anchor":"Check the established pricing guidelines.","explanation":{"en":"Follow the established pricing guidelines. Training examples are not universal prices.","mk":"Следи ги утврдените правила за цени. Примерите од обуката не се универзални цени."}}}]$questions$::jsonb) loop
  desired:=patch->'after';
  select to_jsonb(q) into current_record from evzon_private.exam_questions q where q.id=desired->>'id' for update;
  if current_record=desired then continue; end if;
  if current_record is null or md5(current_record::text) is distinct from patch->>'before_md5' then
   raise exception 'Question % changed since review; no changes made to this batch',desired->>'id';
  end if;
  if current_record->>'test_key' is distinct from desired->>'test_key' or current_record->>'correct' is distinct from desired->>'correct' then
   raise exception 'Question identity or answer-key mapping changed';
  end if;
  if not exists(select 1 from evzon_private.training_units u where u.id=desired->>'unit_id' and u.published and strpos(u.body,desired->>'source_anchor')>0) then
   raise exception 'Supporting guide changed for question %',desired->>'id';
  end if;
  update evzon_private.exam_questions set
   unit_id=desired->>'unit_id',prompt=desired->'prompt',options=desired->'options',
   source_anchor=desired->>'source_anchor',explanation=desired->'explanation'
  where id=desired->>'id';
  if not exists(select 1 from evzon_private.exam_questions q where q.id=desired->>'id' and to_jsonb(q)=desired) then
   raise exception 'Question verification failed';
  end if;
 end loop;
end $release$;
commit;
select '4' as batch, count(*) as bank_questions from evzon_private.exam_questions;

