","test_key":"practice-1","unit_id":"workspace","prompt":{"en":"A colleague asks for your login details. What should you do?","mk":"Колега ги бара твоите податоци за најава. Што треба да направиш?"},"options":[{"id":"a","en":"Keep your login private.","mk":"Чувај ги податоците за најава приватни."},{"id":"b","en":"Share it if the colleague works the next shift.","mk":"Сподели ги ако колегата работи во следната смена."},{"id":"c","en":"Share it after removing your saved drafts.","mk":"Сподели ги откако ќе ги отстраниш зачуваните нацрти."},{"id":"d","en":"Share it only while both of you are online.","mk":"Сподели ги само додека двајцата сте онлајн."}],"correct":"a","source_anchor":"A login you don't share with anyone.","explanation":{"en":"The workspace guide explicitly says not to share your login with anyone.","mk":"Водичот за работен простор изречно вели да не ги споделуваш податоците за најава со никого."}}},{"before_md5":"349c14340b1b7dfafb20f9f43169b3bf","after":{"id":"p1-04","test_key":"practice-1","unit_id":"workspace","prompt":{"en":"Before sending a reply, what account detail should you check?","mk":"Пред да испратиш одговор, што треба да провериш за сметката?"},"options":[{"id":"a","en":"That every creator has the same profile photo.","mk":"Дека сите креаторки имаат иста профилна фотографија."},{"id":"b","en":"That your next shift is scheduled.","mk":"Дека ти е закажана следната смена."},{"id":"c","en":"That all other inboxes are empty.","mk":"Дека сите други сандачиња се празни."},{"id":"d","en":"That you are replying from the correct creator’s account.","mk":"Дека одговараш од сметката на точната креаторка."}],"correct":"d","source_anchor":"always check which account you're typing into before sending.","explanation":{"en":"A dashboard can contain several creator accounts. Check the account before sending.","mk":"Панелот може да содржи повеќе сметки на креаторки. Провери ја сметката пред испраќање."}}},{"before_md5":"eba4895848ff95dfdc40200dc80f1087","after":{"id":"p1-05","test_key":"practice-1","unit_id":"shift-preparation","prompt":{"en":"A customer is waiting for a reply when your shift starts. What should you do first?","mk":"Клиент чека одговор кога започнува твојата смена. Што треба да направиш прво?"},"options":[{"id":"a","en":"Send your usual greeting without reading the chat.","mk":"Испрати го вообичаениот поздрав без да го прочиташ разговорот."},{"id":"b","en":"Repeat the last paid offer immediately.","mk":"Веднаш повтори ја последната платена понуда."},{"id":"c","en":"Read the recent chat so your reply fits the conversation.","mk":"Прочитај го последниот разговор за одговорот да се надоврзе на него."},{"id":"d","en":"Ask the customer to explain everything again.","mk":"Побарај клиентот повторно да објасни сè."}],"correct":"c","source_anchor":"Before replying to someone, check the existing chat history.","explanation":{"en":"Read the existing chat history before replying.","mk":"Прочитај ја историјата на разговорот пред да одговориш."}}}]$questions$::jsonb) loop
  desired:=patch->'after';
  select to_jsonb(q) into current_record from evzon_private.exam_questions q where q.id=desired->>'id' for update;
  if current_record=desired then continue; end if;
  if current_record is null or md5(current_record::text) is distinct from patch->>'before_md5' then
   raise exception 'Question % changed since review; no changes made to this batch',desired->>'id';
  end if;
  if current_record->>'test_key' is distinct from desired->>'test_key' or current_record->>'correct' is distinct from desired->>'correct' then
   raise exception 'Question identity or answer-key mapping changed';
  end if;
  if not exists(select 1 from evzon_private.training_units u where u.id=desired->>'unit_id' and u.published and strpos(u.body,desired->>'source_anchor')>0) then
   raise exception 'Supporting guide changed for question %',desired->>'id';
  end if;
  update evzon_private.exam_questions set
   unit_id=desired->>'unit_id',prompt=desired->'prompt',options=desired->'options',
   source_anchor=desired->>'source_anchor',explanation=desired->'explanation'
  where id=desired->>'id';
  if not exists(select 1 from evzon_private.exam_questions q where q.id=desired->>'id' and to_jsonb(q)=desired) then
   raise exception 'Question verification failed';
  end if;
 end loop;
end $release$;
commit;
select '7' as batch, count(*) as bank_questions from evzon_private.exam_questions;

