begin
 for patch in select value from jsonb_array_elements($questions$[{"before_md5":"c3aa242b2d671983fcdee88d07bdf594","after":{"id":"p2-06","test_key":"practice-2","unit_id":"flow-opening","prompt":{"en":"Someone says hello for the first time. What is a good start?","mk":"Некој првпат те поздравува. Како е добро да започнеш?"},"options":[{"id":"a","en":"Greet them and begin a normal conversation.","mk":"Поздрави го и започни нормален разговор."},{"id":"b","en":"Send a paid offer before replying.","mk":"Испрати платена понуда пред да одговориш."},{"id":"c","en":"Ask for a payment before talking.","mk":"Побарај плаќање пред да разговараш."},{"id":"d","en":"Wait until they buy before saying hello.","mk":"Почекај да купи пред да го поздравиш."}],"correct":"a","source_anchor":"Start naturally, as a normal person would. Establish a conversation before attempting to sell anything.","explanation":{"en":"Start naturally and build a conversation before trying to sell.","mk":"Започни природно и изгради разговор пред да се обидеш да продадеш."}}},{"before_md5":"aaf46e713fc06e9dc8cad6dd9483c23a","after":{"id":"p2-07","test_key":"practice-2","unit_id":"flow-opening","prompt":{"en":"The customer becomes uncomfortable when the chat gets more personal. What should you do?","mk":"На клиентот му станува непријатно кога разговорот станува поличен. Што треба да направиш?"},"options":[{"id":"a","en":"Keep pushing the same tone.","mk":"Продолжи да го наметнуваш истиот тон."},{"id":"b","en":"Send a paid offer immediately.","mk":"Веднаш испрати платена понуда."},{"id":"c","en":"Ignore their reaction.","mk":"Игнорирај ја неговата реакција."},{"id":"d","en":"Return to normal conversation without pushing an offer.","mk":"Врати се на нормален разговор без да наметнуваш понуда."}],"correct":"d","source_anchor":"If the customer pulls back, take the no-pitch path instead.","explanation":{"en":"If the customer pulls back, stop pushing and keep the conversation normal.","mk":"Ако клиентот се повлече, престани да притискаш и задржи нормален разговор."}}},{"before_md5":"898c30e0c5aa4f399b05fa012108a4bf","after":{"id":"p2-08","test_key":"practice-2","unit_id":"flow-opening","prompt":{"en":"A customer is replying politely. Does that automatically mean they want a more intimate conversation?","mk":"Клиент учтиво одговара. Дали тоа автоматски значи дека сака поинтимен разговор?"},"options":[{"id":"a","en":"Yes. Every reply means they want that.","mk":"Да. Секој одговор значи дека го сака тоа."},{"id":"b","en":"Yes, if they have bought something before.","mk":"Да, ако претходно купил нешто."},{"id":"c","en":"No. Pay attention to whether they actually show interest.","mk":"Не. Внимавај дали навистина покажува интерес."},{"id":"d","en":"Yes, if you have already sent enough messages.","mk":"Да, ако веќе си испратил доволно пораки."}],"correct":"c","source_anchor":"Do not assume that a customer is interested simply because they continue replying.","explanation":{"en":"Continuing to reply does not by itself show interest in a change of tone.","mk":"Самото продолжување со одговори не покажува интерес за промена на тонот."}}},{"before_md5":"067bec5f5fd8759939424767a7208311","after":{"id":"p2-09","test_key":"practice-2","unit_id":"flow-opening","prompt":{"en":"The customer tells you what they enjoy and is comfortable chatting. How should you respond?","mk":"Клиентот кажува што му се допаѓа и се чувствува пријатно во разговорот. Како треба да одговориш?"},"options":[{"id":"a","en":"Ignore their preferences.","mk":"Игнорирај ги неговите желби."},{"id":"b","en":"Match their energy and use what they have shared.","mk":"Усогласи се со неговата енергија и користи го она што го споделил."},{"id":"c","en":"Use the same unrelated answer for everyone.","mk":"Користи ист неповрзан одговор за сите."},{"id":"d","en":"Change the subject after every message.","mk":"Менувај ја темата по секоја порака."}],"correct":"b","source_anchor":"- Match their energy.\n- Build on what they say they like.","explanation":{"en":"Match their energy and build on what they say they like.","mk":"Усогласи се со неговата енергија и надоврзи се на она што кажува дека му се допаѓа."}}},{"before_md5":"b9ccc3d9893fcf3326fed77f3466fcb4","after":{"id":"p2-10","test_key":"practice-2","unit_id":"flow-purchase","prompt":{"en":"A customer opens the paid content and says they enjoyed it. What should you do next?","mk":"Клиент ја отвора платената содржина и вели дека му се допаднала. Што треба да направиш потоа?"},"options":[{"id":"a","en":"Respond to their reaction and keep the conversation going.","mk":"Одговори на неговата реакција и продолжи го разговорот."},{"id":"b","en":"Disappear because the sale is finished.","mk":"Исчезни затоа што продажбата е завршена."},{"id":"c","en":"Send another offer without reading their response.","mk":"Испрати друга понуда без да го прочиташ одговорот."},{"id":"d","en":"Restart the introduction as if you have never spoken.","mk":"Започни го воведот одново како никогаш да не сте разговарале."}],"correct":"a","source_anchor":"Continue the conversation instead of ending it immediately.","explanation":{"en":"A successful purchase is a reason to continue the conversation, not end it abruptly.","mk":"Успешното купување е причина да го продолжиш разговорот, а не нагло да го завршиш."}}}]$questions$::jsonb) loop
  desired:=patch->'after';
  select to_jsonb(q) into current_record from evzon_private.exam_questions q where q.id=desired->>'id' for update;
  if current_record=desired then continue; end if;
  if current_record is null or md5(current_record::text) is distinct from patch->>'before_md5' then
   raise exception 'Question % changed since review; no changes made to this batch',desired->>'id';
  end if;
  if current_record->>'test_key' is distinct from desired->>'test_key' or current_record->>'correct' is distinct from desired->>'correct' then
   raise exception 'Question identity or answer-key mapping changed';
  end if;
  if not exists(select 1 from evzon_private.training_units u where u.id=desired->>'unit_id' and u.published and strpos(u.body,desired->>'source_anchor')>0) then
   raise exception 'Supporting guide changed for question %',desired->>'id';
  end if;
  update evzon_private.exam_questions set
   unit_id=desired->>'unit_id',prompt=desired->'prompt',options=desired->'options',
   source_anchor=desired->>'source_anchor',explanation=desired->'explanation'
  where id=desired->>'id';
  if not exists(select 1 from evzon_private.exam_questions q where q.id=desired->>'id' and to_jsonb(q)=desired) then
   raise exception 'Question verification failed';
  end if;
 end loop;
end $release$;
commit;
select '13' as batch, count(*) as bank_questions from evzon_private.exam_questions;

