begin
 for patch in select value from jsonb_array_elements($questions$[{"before_md5":"bce6412acd460fa8b15a8ca6ec945a6e","after":{"id":"p2-21","test_key":"practice-2","unit_id":"flow-no-pitch","prompt":{"en":"The customer is finished buying for now. How can the chat continue or end?","mk":"Клиентот засега завршил со купување. Како може да продолжи или да заврши разговорот?"},"options":[{"id":"a","en":"Delete the interaction if there was no purchase.","mk":"Избриши ја интеракцијата ако немало купување."},{"id":"b","en":"End warmly or continue normal conversation.","mk":"Заврши срдечно или продолжи со нормален разговор."},{"id":"c","en":"End coldly unless a new purchase is made.","mk":"Заврши студено освен ако нема ново купување."},{"id":"d","en":"Restart the paid offer immediately in every case.","mk":"Веднаш повторно започни ја платената понуда во секој случај."}],"correct":"b","source_anchor":"Wrap up warmly or continue chatting as normal.","explanation":{"en":"Continue normal conversation or end warmly, without pressure to buy again.","mk":"Продолжи нормално или заврши топло, без притисок повторно да купи."}}},{"before_md5":"902b7c1d212312ab33bdafd61652620c","after":{"id":"p2-22","test_key":"practice-2","unit_id":"rapport-practice","prompt":{"en":"A friendly conversation does not lead to a sale. Is that always a problem?","mk":"Пријателски разговор не води до продажба. Дали тоа секогаш е проблем?"},"options":[{"id":"a","en":"Some conversations can remain noncommercial.","mk":"Некои разговори можат да останат некомерцијални."},{"id":"b","en":"Every conversation must eventually include a paid offer.","mk":"Секој разговор мора на крај да вклучи платена понуда."},{"id":"c","en":"A friendly chat is automatically a failed interaction.","mk":"Пријателски разговор автоматски е неуспешна интеракција."},{"id":"d","en":"A silence must always be filled with a sales pitch.","mk":"Тишината секогаш мора да се пополни со продажна понуда."}],"correct":"a","source_anchor":"Accept that some conversations may remain noncommercial.","explanation":{"en":"Some conversations can stay friendly without becoming a sale.","mk":"Некои разговори можат да останат пријателски без да станат продажба."}}},{"before_md5":"bab2545768c086f36c788467a4ad188a","after":{"id":"p2-23","test_key":"practice-2","unit_id":"rapport-practice","prompt":{"en":"A fan returns after a trip they told you about. What is a good way to continue?","mk":"Фан се враќа по патување за кое ти кажал. Како е добро да го продолжиш разговорот?"},"options":[{"id":"a","en":"Ask them again whether they have any interests at all.","mk":"Повторно прашај дали воопшто имаат некакви интереси."},{"id":"b","en":"Ignore the earlier detail and send a generic pitch.","mk":"Игнорирај го претходниот податок и испрати општа понуда."},{"id":"c","en":"Use the same unrelated introduction every time.","mk":"Користи го истиот неповрзан вовед секој пат."},{"id":"d","en":"Refer back to the trip naturally.","mk":"Природно наврати се на патувањето."}],"correct":"d","source_anchor":"If a subscriber tells you about work, a hobby, a trip, or something they are looking forward to, use that information naturally in a later conversation.","explanation":{"en":"The rapport guide recommends bringing up relevant details naturally in later conversations.","mk":"Водичот за градење однос препорачува природно да ги спомнуваш релевантните детали во подоцнежни разговори."}}},{"before_md5":"c1f8b75052aa98b6ebd22bbac9f34940","after":{"id":"p2-24","test_key":"practice-2","unit_id":"rapport-practice","prompt":{"en":"A fan tells you about their day. What is a good response?","mk":"Фан ти раскажува за својот ден. Кој е добар одговор?"},"options":[{"id":"a","en":"Repeat the exact same question without using their answer.","mk":"Повтори го истото прашање без да го искористиш одговорот."},{"id":"b","en":"Treat their answer as an automatic buying signal.","mk":"Сметај го одговорот за автоматски сигнал за купување."},{"id":"c","en":"Show interest with a relevant follow-up question.","mk":"Покажи интерес со релевантно дополнително прашање."},{"id":"d","en":"Immediately change to an unrelated topic.","mk":"Веднаш премини на неповрзана тема."}],"correct":"c","source_anchor":"Instead of changing topics immediately, show interest in the answer.","explanation":{"en":"The guide says to show interest in the answer instead of immediately changing topics.","mk":"Водичот вели да покажеш интерес за одговорот наместо веднаш да ја смениш темата."}}},{"before_md5":"4b9e8cb5dd36cc3b8dd8ec24f9b9b319","after":{"id":"p2-25","test_key":"practice-2","unit_id":"rapport-practice","prompt":{"en":"You are tempted to make a promise for the creator without knowing if it is possible. What should you do?","mk":"Сакаш да ветиш нешто во име на креаторката, но не знаеш дали е возможно. Што треба да направиш?"},"options":[{"id":"a","en":"Promise it now and check later.","mk":"Вети сега, па провери подоцна."},{"id":"b","en":"Avoid promises you cannot keep.","mk":"Избегнувај ветувања што не можеш да ги исполниш."},{"id":"c","en":"Promise anything that keeps the chat going.","mk":"Вети сè што го одржува разговорот."},{"id":"d","en":"Use the same promise for every fan.","mk":"Користи го истото ветување за секој фан."}],"correct":"b","source_anchor":"Do not pretend to have personal experiences or make commitments on behalf of the creator that you cannot fulfill.","explanation":{"en":"Do not make commitments on the creator’s behalf that you cannot fulfill.","mk":"Не преземај обврски во име на креаторката што не можеш да ги исполниш."}}}]$questions$::jsonb) loop
  desired:=patch->'after';
  select to_jsonb(q) into current_record from evzon_private.exam_questions q where q.id=desired->>'id' for update;
  if current_record=desired then continue; end if;
  if current_record is null or md5(current_record::text) is distinct from patch->>'before_md5' then
   raise exception 'Question % changed since review; no changes made to this batch',desired->>'id';
  end if;
  if current_record->>'test_key' is distinct from desired->>'test_key' or current_record->>'correct' is distinct from desired->>'correct' then
   raise exception 'Question identity or answer-key mapping changed';
  end if;
  if not exists(select 1 from evzon_private.training_units u where u.id=desired->>'unit_id' and u.published and strpos(u.body,desired->>'source_anchor')>0) then
   raise exception 'Supporting guide changed for question %',desired->>'id';
  end if;
  update evzon_private.exam_questions set
   unit_id=desired->>'unit_id',prompt=desired->'prompt',options=desired->'options',
   source_anchor=desired->>'source_anchor',explanation=desired->'explanation'
  where id=desired->>'id';
  if not exists(select 1 from evzon_private.exam_questions q where q.id=desired->>'id' and to_jsonb(q)=desired) then
   raise exception 'Question verification failed';
  end if;
 end loop;
end $release$;
commit;
select '16' as batch, count(*) as bank_questions from evzon_private.exam_questions;

