 for patch in select value from jsonb_array_elements($questions$[{"before_md5":"42df4201373eab3ceda6ad9956b0805a","after":{"id":"p3-11","test_key":"practice-3","unit_id":"flow-no-unlock","prompt":{"en":"The customer clearly says no after you explain the offer. How should you respond?","mk":"Клиентот јасно вели не откако ја објасниш понудата. Како треба да одговориш?"},"options":[{"id":"a","en":"Treat the refusal as a completed purchase.","mk":"Третирај го одбивањето како завршено купување."},{"id":"b","en":"Accept their answer and move on from the offer.","mk":"Прифати го одговорот и продолжи понатаму без таа понуда."},{"id":"c","en":"Repeat the offer until they stop replying.","mk":"Повторувај ја понудата додека не престанат да одговараат."},{"id":"d","en":"Keep asking them to justify their refusal.","mk":"Продолжи да бараш да го оправдаат одбивањето."}],"correct":"b","source_anchor":"If the customer clearly declines, accept the answer.","explanation":{"en":"Accept the answer instead of repeating the offer indefinitely.","mk":"Прифати го одговорот наместо бескрајно да ја повторуваш понудата."}}},{"before_md5":"a0f265b83c50706c63ef5a4dfb8548b3","after":{"id":"p3-12","test_key":"practice-3","unit_id":"flow-no-pitch","prompt":{"en":"The customer does not like the paid content. What tone should you use now?","mk":"На клиентот не му се допаѓа платената содржина. Каков тон треба да користиш сега?"},"options":[{"id":"a","en":"Slow down and move back to normal chat.","mk":"Забави и врати се на нормален разговор."},{"id":"b","en":"Push a more intense conversation.","mk":"Наметни поинтензивен разговор."},{"id":"c","en":"Send several new offers in a row.","mk":"Испрати неколку нови понуди по ред."},{"id":"d","en":"Ignore what they said.","mk":"Игнорирај го она што го кажал."}],"correct":"a","source_anchor":"Move back toward normal chat.","explanation":{"en":"Lower the intensity and return toward normal conversation.","mk":"Намали го интензитетот и врати се кон нормален разговор."}}},{"before_md5":"301642bda9c8dbc0ab1f6860479cea38","after":{"id":"p3-13","test_key":"practice-3","unit_id":"flow-no-pitch","prompt":{"en":"A customer says, “I’m not buying today.” How should you leave the conversation?","mk":"Клиент вели: „Денес не купувам.“ Како треба да го завршиш разговорот?"},"options":[{"id":"a","en":"Treat it as a permanent rejection of every future conversation.","mk":"Третирај го како трајно одбивање на секој иден разговор."},{"id":"b","en":"End abruptly so they know a purchase was expected.","mk":"Заврши нагло за да знаат дека се очекувало купување."},{"id":"c","en":"Keep the same offer active until they change their answer.","mk":"Продолжи со истата понуда додека не го сменат одговорот."},{"id":"d","en":"Wrap up warmly or continue normally, leaving room for future interaction.","mk":"Заврши топло или продолжи нормално, оставајќи простор за идна интеракција."}],"correct":"d","source_anchor":"Do not treat a refusal to purchase today as a permanent rejection.","explanation":{"en":"The guide recommends a warm ending or normal conversation and says a refusal today is not a permanent rejection.","mk":"Водичот препорачува топол завршеток или нормален разговор и вели дека денешното одбивање не е трајно одбивање."}}},{"before_md5":"a3fe19364a2872030e66254ee16521ec","after":{"id":"p3-14","test_key":"practice-3","unit_id":"aftercare","prompt":{"en":"A customer stops buying but still wants to talk. What should you do?","mk":"Клиент престанува да купува, но сè уште сака да разговара. Што треба да направиш?"},"options":[{"id":"a","en":"Stop replying because they stopped paying.","mk":"Престани да одговараш затоа што престанал да плаќа."},{"id":"b","en":"Ask them to buy again before you talk.","mk":"Побарај повторно да купи пред да разговарате."},{"id":"c","en":"Continue giving them attention and chatting normally.","mk":"Продолжи да му посветуваш внимание и да разговараш нормално."},{"id":"d","en":"Assume they no longer care about the account.","mk":"Претпостави дека сметката веќе не го интересира."}],"correct":"c","source_anchor":"The important instruction is not to treat the end of purchasing as the end of the interaction.","explanation":{"en":"The end of purchases does not have to be the end of the conversation.","mk":"Крајот на купувањето не мора да биде крај на разговорот."}}},{"before_md5":"f167c35c15a2cfbc28c18d9656abb054","after":{"id":"p3-15","test_key":"practice-3","unit_id":"aftercare","prompt":{"en":"A customer has just bought content. What is a good follow-up?","mk":"Клиент штотуку купил содржина. Како е добро да продолжиш?"},"options":[{"id":"a","en":"Return only when they purchase another item.","mk":"Врати се само кога ќе купи друга содржина."},{"id":"b","en":"Thank the customer, respond warmly, and check their satisfaction.","mk":"Заблагодари му се на клиентот, одговори топло и провери дали е задоволен."},{"id":"c","en":"Send the next payment request before responding to them.","mk":"Испрати го следното барање за плаќање пред да му одговориш."},{"id":"d","en":"Leave the chat because the transaction is finished.","mk":"Напушти го разговорот бидејќи трансакцијата е завршена."}],"correct":"b","source_anchor":"Thank them for the purchase, respond to them warmly, and make sure they are satisfied with the content.","explanation":{"en":"Thank them, respond warmly and check that they are satisfied.","mk":"Заблагодари се, одговори топло и провери дали е задоволен."}}}]$questions$::jsonb) loop
  desired:=patch->'after';
  select to_jsonb(q) into current_record from evzon_private.exam_questions q where q.id=desired->>'id' for update;
  if current_record=desired then continue; end if;
  if current_record is null or md5(current_record::text) is distinct from patch->>'before_md5' then
   raise exception 'Question % changed since review; no changes made to this batch',desired->>'id';
  end if;
  if current_record->>'test_key' is distinct from desired->>'test_key' or current_record->>'correct' is distinct from desired->>'correct' then
   raise exception 'Question identity or answer-key mapping changed';
  end if;
  if not exists(select 1 from evzon_private.training_units u where u.id=desired->>'unit_id' and u.published and strpos(u.body,desired->>'source_anchor')>0) then
   raise exception 'Supporting guide changed for question %',desired->>'id';
  end if;
  update evzon_private.exam_questions set
   unit_id=desired->>'unit_id',prompt=desired->'prompt',options=desired->'options',
   source_anchor=desired->>'source_anchor',explanation=desired->'explanation'
  where id=desired->>'id';
  if not exists(select 1 from evzon_private.exam_questions q where q.id=desired->>'id' and to_jsonb(q)=desired) then
   raise exception 'Question verification failed';
  end if;
 end loop;
end $release$;
