 for patch in select value from jsonb_array_elements($questions$[{"before_md5":"b800142b4e9f11906bd529fe529bf12f","after":{"id":"p4-01","test_key":"practice-4","unit_id":"support-service","prompt":{"en":"A fan asks to move the chat to WhatsApp. What should you do?","mk":"Фан бара разговорот да се премести на WhatsApp. Што треба да направиш?"},"options":[{"id":"a","en":"Move it if the fan has purchased before.","mk":"Премести го ако фанот претходно купувал."},{"id":"b","en":"Use a private account for the rest of the chat.","mk":"Користи приватна сметка за остатокот од разговорот."},{"id":"c","en":"Move it temporarily and return after the next sale.","mk":"Привремено премести го и врати се по следната продажба."},{"id":"d","en":"Keep the conversation on the platform.","mk":"Задржи го разговорот на платформата."}],"correct":"d","source_anchor":"Keep the rule firm, never leave the platform","explanation":{"en":"The support guide says to keep the rule firm and never move the conversation off-platform.","mk":"Водичот за поддршка вели правилото да се задржи цврсто и разговорот никогаш да не се преместува надвор од платформата."}}},{"before_md5":"a86eed5a21c8874a42a783cb9c981480","after":{"id":"p4-02","test_key":"practice-4","unit_id":"support-boundaries","prompt":{"en":"A fan requests content that is not allowed. How should you respond?","mk":"Фан бара содржина што не е дозволена. Како треба да одговориш?"},"options":[{"id":"a","en":"Promise it now and check the rules after payment.","mk":"Вети го сега и провери ги правилата по плаќањето."},{"id":"b","en":"Ask them to make the request on another platform.","mk":"Побарај барањето да го испратат на друга платформа."},{"id":"c","en":"Decline that request and redirect to safe, allowed content.","mk":"Одбиј го тоа барање и насочи го кон безбедна, дозволена содржина."},{"id":"d","en":"Accept it if the fan offers a higher payment.","mk":"Прифати го ако фанот понуди повисока уплата."}],"correct":"c","source_anchor":"Redirect to safe content, never entertain illegal/off-limits requests","explanation":{"en":"The guide says never to entertain illegal or off-limits requests and to redirect toward safe content.","mk":"Водичот вели никогаш да не се прифаќаат незаконски или недозволени барања и разговорот да се насочи кон безбедна содржина."}}},{"before_md5":"8342e9dafe2a3c04c5bc085a7d7fce10","after":{"id":"p4-03","test_key":"practice-4","unit_id":"support-boundaries","prompt":{"en":"You are unsure whether a request is allowed. Who should you contact before continuing?","mk":"Не си сигурен дали барањето е дозволено. Кого треба да контактираш пред да продолжиш?"},"options":[{"id":"a","en":"Respond based only on what another account once did.","mk":"Одговори само според тоа што некогаш направил друг профил."},{"id":"b","en":"Pause and contact Stefan before continuing.","mk":"Застани и контактирај го Стефан пред да продолжиш."},{"id":"c","en":"Agree provisionally so the fan stays interested.","mk":"Привремено согласи се за фанот да остане заинтересиран."},{"id":"d","en":"Let the fan decide which rules apply.","mk":"Остави фанот да одлучи кои правила важат."}],"correct":"b","source_anchor":"If you are unsure, pause the conversation and contact Stefan before responding further.","explanation":{"en":"The guide explicitly tells an unsure chatter to pause and contact Stefan before continuing.","mk":"Водичот изречно му кажува на чатерот што не е сигурен да застане и да го контактира Стефан пред да продолжи."}}},{"before_md5":"32bf01e4d85dac6af4d80ab1a950aa97","after":{"id":"p4-04","test_key":"practice-4","unit_id":"support-service","prompt":{"en":"A fan threatens a chargeback or asks for a refund. What should you do internally?","mk":"Фан се заканува со поврат на плаќањето или бара рефундација. Што треба да направиш во тимот?"},"options":[{"id":"a","en":"Notify Stefan.","mk":"Извести го Стефан."},{"id":"b","en":"Handle it without telling anyone.","mk":"Решавај го без да известиш никого."},{"id":"c","en":"Promise a refund without checking with Stefan.","mk":"Вети рефундација без проверка со Стефан."},{"id":"d","en":"Delete the conversation before reporting it.","mk":"Избриши го разговорот пред да го пријавиш."}],"correct":"a","source_anchor":"Notify Stefan of this","explanation":{"en":"The chargeback and refund section explicitly instructs the chatter to notify Stefan.","mk":"Делот за поврат преку банка и рефундација изречно му наложува на чатерот да го извести Стефан."}}},{"before_md5":"e23e5af5d596b4e3840f04aded38adcc","after":{"id":"p4-05","test_key":"practice-4","unit_id":"support-service","prompt":{"en":"A fan repeatedly asks for a discount. What should you do about the price?","mk":"Фан постојано бара попуст. Што треба да направиш со цената?"},"options":[{"id":"a","en":"Lower the price after each repeated request.","mk":"Намалувај ја цената по секое повторено барање."},{"id":"b","en":"Offer a private discount outside the approved terms.","mk":"Понуди приватен попуст надвор од одобрените услови."},{"id":"c","en":"Let the fan choose any price for the same item.","mk":"Остави фанот да одбере која било цена за истата содржина."},{"id":"d","en":"Keep to the price listing instead of lowering the price.","mk":"Држи се до ценовникот наместо да ја намалуваш цената."}],"correct":"d","source_anchor":"always stick to price listing","explanation":{"en":"The support guide says to set boundaries, never lower prices, and stick to the price listing.","mk":"Водичот за поддршка вели да се постават граници, да не се намалуваат цените и да се следи ценовникот."}}}]$questions$::jsonb) loop
  desired:=patch->'after';
  select to_jsonb(q) into current_record from evzon_private.exam_questions q where q.id=desired->>'id' for update;
  if current_record=desired then continue; end if;
  if current_record is null or md5(current_record::text) is distinct from patch->>'before_md5' then
   raise exception 'Question % changed since review; no changes made to this batch',desired->>'id';
  end if;
  if current_record->>'test_key' is distinct from desired->>'test_key' or current_record->>'correct' is distinct from desired->>'correct' then
   raise exception 'Question identity or answer-key mapping changed';
  end if;
  if not exists(select 1 from evzon_private.training_units u where u.id=desired->>'unit_id' and u.published and strpos(u.body,desired->>'source_anchor')>0) then
   raise exception 'Supporting guide changed for question %',desired->>'id';
  end if;
  update evzon_private.exam_questions set
   unit_id=desired->>'unit_id',prompt=desired->'prompt',options=desired->'options',
   source_anchor=desired->>'source_anchor',explanation=desired->'explanation'
  where id=desired->>'id';
  if not exists(select 1 from evzon_private.exam_questions q where q.id=desired->>'id' and to_jsonb(q)=desired) then
   raise exception 'Question verification failed';
  end if;
 end loop;
end $release$;
commit;
