 for patch in select value from jsonb_array_elements($questions$[{"before_md5":"45dc51e5707d356c7322fae96fcc7c50","after":{"id":"p4-16","test_key":"practice-4","unit_id":"daily-offers","prompt":{"en":"What is custom content?","mk":"Што е содржина по нарачка?"},"options":[{"id":"a","en":"Material created specifically for an individual customer’s request.","mk":"Материјал создаден посебно според барање на поединечен клиент."},{"id":"b","en":"Any existing item copied into a new message.","mk":"Секоја постојна содржина копирана во нова порака."},{"id":"c","en":"A mass message sent to all followers.","mk":"Масовна порака испратена до сите следбеници."},{"id":"d","en":"A standard item whose caption has been shortened.","mk":"Стандардна содржина чиј опис е скратен."}],"correct":"a","source_anchor":"Custom content is material created specifically for an individual customer's request.","explanation":{"en":"The custom-content section defines it as material created specifically for an individual customer’s request.","mk":"Делот за содржина по нарачка ја дефинира како материјал создаден посебно според барање на поединечен клиент."}}},{"before_md5":"dc5d842ff3c604d3905d1c26bef14d38","after":{"id":"p4-17","test_key":"practice-4","unit_id":"daily-offers","prompt":{"en":"Before accepting a custom request, what should you confirm with the creator?","mk":"Пред да прифатиш барање за содржина по нарачка, што треба да потврдиш со креаторката?"},"options":[{"id":"a","en":"That the customer is willing to accept any substitute.","mk":"Дека клиентот сака да прифати каква било замена."},{"id":"b","en":"That you can promise it before she has responded.","mk":"Дека можеш да ја ветиш пред таа да одговори."},{"id":"c","en":"That an old example price applies without checking.","mk":"Дека важи стара пример-цена без проверка."},{"id":"d","en":"That she is willing and able to produce it.","mk":"Дека сака и може да ја изработи."}],"correct":"d","source_anchor":"make sure the creator is willing and able to produce it.","explanation":{"en":"The custom-request procedure explicitly requires confirming that the creator is willing and able to produce the requested content.","mk":"Постапката за нарачки изречно бара потврда дека креаторката сака и може да ја изработи побараната содржина."}}},{"before_md5":"f5bb53d466b9b4058700a452c3839381","after":{"id":"p4-18","test_key":"practice-4","unit_id":"daily-offers","prompt":{"en":"A customer asks for custom content. What details should you clarify?","mk":"Клиент бара содржина по нарачка. Кои детали треба да ги појасниш?"},"options":[{"id":"a","en":"Only whether they have bought an existing item before.","mk":"Само дали претходно купиле постојна содржина."},{"id":"b","en":"Only the date on which they subscribed.","mk":"Само датумот на кој се претплатиле."},{"id":"c","en":"The type of content, requested duration and relevant preferences.","mk":"Видот на содржината, бараната должина и соодветните преференции."},{"id":"d","en":"Only the amount they are ready to send immediately.","mk":"Само износот што се подготвени веднаш да го испратат."}],"correct":"c","source_anchor":"Find out the type of content, requested duration, and any relevant preferences.","explanation":{"en":"The guide says to understand the request by finding out its type, duration and relevant preferences.","mk":"Водичот вели барањето да се разбере преку појаснување на видот, должината и соодветните преференции."}}},{"before_md5":"64a1ec2ee8f5839cf6f7e48107e29b1a","after":{"id":"p4-19","test_key":"practice-4","unit_id":"daily-offers","prompt":{"en":"Before promising when a custom video will be ready, what do you need?","mk":"Што ти е потребно пред да ветиш кога ќе биде готово видео по нарачка?"},"options":[{"id":"a","en":"A higher payment, regardless of creator availability.","mk":"Повисока уплата, без оглед на достапноста на креаторката."},{"id":"b","en":"Authorization from the creator.","mk":"Одобрение од креаторката."},{"id":"c","en":"Your estimate based on the last customer’s delivery.","mk":"Твоја проценка според испораката за претходниот клиент."},{"id":"d","en":"A promise that you will ask the creator afterward.","mk":"Ветување дека подоцна ќе ја прашаш креаторката."}],"correct":"b","source_anchor":"Never promise a custom video, delivery date, or feature without the creator's authorization.","explanation":{"en":"The guide forbids promising a custom video, delivery date or feature without the creator’s authorization.","mk":"Водичот забранува ветување видео по нарачка, датум на испорака или карактеристика без одобрение од креаторката."}}},{"before_md5":"9ebea246e98b2893e9c75ca3230757a6","after":{"id":"p4-20","test_key":"practice-4","unit_id":"daily-offers","prompt":{"en":"An approved custom order is agreed. How should the customer pay?","mk":"Договорена е одобрена содржина по нарачка. Како треба да плати клиентот?"},"options":[{"id":"a","en":"Through the approved platform process.","mk":"Преку одобрената постапка на платформата."},{"id":"b","en":"Through the chatter’s personal payment account.","mk":"Преку личната платежна сметка на чатерот."},{"id":"c","en":"Through whichever off-platform method the fan suggests.","mk":"Преку кој било метод надвор од платформата што ќе го предложи фанот."},{"id":"d","en":"Without confirming the request or agreed terms.","mk":"Без потврдување на барањето или договорените услови."}],"correct":"a","source_anchor":"arrange payment through the approved platform process.","explanation":{"en":"The custom-content procedure says to confirm the request and arrange payment through the approved platform process.","mk":"Постапката за содржина по нарачка вели барањето да се потврди и плаќањето да се организира преку одобрената постапка на платформата."}}}]$questions$::jsonb) loop
  desired:=patch->'after';
  select to_jsonb(q) into current_record from evzon_private.exam_questions q where q.id=desired->>'id' for update;
  if current_record=desired then continue; end if;
  if current_record is null or md5(current_record::text) is distinct from patch->>'before_md5' then
   raise exception 'Question % changed since review; no changes made to this batch',desired->>'id';
  end if;
  if current_record->>'test_key' is distinct from desired->>'test_key' or current_record->>'correct' is distinct from desired->>'correct' then
   raise exception 'Question identity or answer-key mapping changed';
  end if;
  if not exists(select 1 from evzon_private.training_units u where u.id=desired->>'unit_id' and u.published and strpos(u.body,desired->>'source_anchor')>0) then
   raise exception 'Supporting guide changed for question %',desired->>'id';
  end if;
  update evzon_private.exam_questions set
   unit_id=desired->>'unit_id',prompt=desired->'prompt',options=desired->'options',
   source_anchor=desired->>'source_anchor',explanation=desired->'explanation'
  where id=desired->>'id';
  if not exists(select 1 from evzon_private.exam_questions q where q.id=desired->>'id' and to_jsonb(q)=desired) then
   raise exception 'Question verification failed';
  end if;
 end loop;
end $release$;
commit;
