 for patch in select value from jsonb_array_elements($questions$[{"before_md5":"9d7715b9f3b0d9e0d0e5937d09f4d4fb","after":{"id":"p5-06","test_key":"practice-5","unit_id":"records-retention","prompt":{"en":"You want to reconnect with previous customers. Where should you start?","mk":"Сакаш повторно да стапиш во контакт со претходни клиенти. Од каде треба да започнеш?"},"options":[{"id":"a","en":"Send every past customer a paid offer immediately.","mk":"Веднаш испрати платена понуда до секој поранешен клиент."},{"id":"b","en":"Delete old chats and use a new greeting for everyone.","mk":"Избриши ги старите разговори и користи нов поздрав за сите."},{"id":"c","en":"Ignore all earlier purchases and replies.","mk":"Игнорирај ги сите претходни купувања и одговори."},{"id":"d","en":"Review older chats for people who have not been contacted recently.","mk":"Прегледај постари разговори со луѓе што не биле контактирани неодамна."}],"correct":"d","source_anchor":"Refiltering means going back through previous subscribers and customers to identify people who have not been contacted recently.","explanation":{"en":"Review earlier customers and their conversations before choosing a suitable follow-up.","mk":"Прегледај ги претходните клиенти и нивните разговори пред да одбереш соодветно продолжување."}}},{"before_md5":"190c263ebe063d6d50c7b1e699646007","after":{"id":"p5-07","test_key":"practice-5","unit_id":"records-retention","prompt":{"en":"Before messaging a fan who has been inactive, what should you review?","mk":"Што треба да прегледаш пред да му пишеш на фан што бил неактивен?"},"options":[{"id":"a","en":"Only the creator’s latest upload.","mk":"Само последната објавена содржина на креаторката."},{"id":"b","en":"The number of messages you sent to other customers.","mk":"Бројот на пораки што си им ги испратил на други клиенти."},{"id":"c","en":"The previous discussion, last purchase and last response.","mk":"Претходниот разговор, последното купување и последниот одговор."},{"id":"d","en":"Only whether a new mass message is scheduled.","mk":"Само дали е закажана нова масовна порака."}],"correct":"c","source_anchor":"Check what was discussed previously, including their last purchase or last response.","explanation":{"en":"The refiltering steps say to review what was previously discussed, including the last purchase or reply.","mk":"Чекорите за повторно филтрирање бараат преглед на претходниот разговор, вклучувајќи го последното купување или одговор."}}},{"before_md5":"2601cb8a9a635b5223df52dbc4269ccf","after":{"id":"p5-08","test_key":"practice-5","unit_id":"records-retention","prompt":{"en":"You contact an old customer again. What should the first message aim to do?","mk":"Повторно контактираш стар клиент. Што треба да постигне првата порака?"},"options":[{"id":"a","en":"Move them directly into a VIP offer.","mk":"Веднаш да им се понуди VIP-пакет."},{"id":"b","en":"Restart the conversation.","mk":"Повторно да се започне разговор."},{"id":"c","en":"Immediately send the next paid offer.","mk":"Веднаш да се испрати следната платена понуда."},{"id":"d","en":"Replace their previous purchase history.","mk":"Да се замени нивната претходна историја на купувања."}],"correct":"b","source_anchor":"The objective is to start a conversation, not immediately send another paid offer.","explanation":{"en":"Start a conversation instead of immediately sending another paid offer.","mk":"Започни разговор наместо веднаш да испратиш друга платена понуда."}}},{"before_md5":"ed1db4c8c88d3fc9c9b5b0b21ea2c5bb","after":{"id":"p5-09","test_key":"practice-5","unit_id":"records-retention","prompt":{"en":"A customer has been quiet for several weeks. What is a reasonable approach?","mk":"Клиент не одговара неколку недели. Кој е разумен пристап?"},"options":[{"id":"a","en":"They may still return, so an occasional relevant follow-up can be appropriate.","mk":"Сè уште може да се врати, па повремено соодветно контактирање може да има смисла."},{"id":"b","en":"They will never return and their history has no further use.","mk":"Никогаш нема да се врати и неговата историја веќе не е корисна."},{"id":"c","en":"They must now receive paid offers every day.","mk":"Сега мора да добива платени понуди секој ден."},{"id":"d","en":"Their earlier spending category should automatically become VIP.","mk":"Нивната претходна категорија за трошење треба автоматски да стане VIP."}],"correct":"a","source_anchor":"A customer becoming inactive does not automatically mean they will never return.","explanation":{"en":"The guide says inactivity does not automatically mean the customer will never return and recommends occasional, relevant follow-ups.","mk":"Водичот вели дека неактивноста не значи автоматски дека клиентот никогаш нема да се врати и препорачува повремени, релевантни пораки."}}},{"before_md5":"476bec7417a645fd5b9dc23666e64435","after":{"id":"p5-10","test_key":"practice-5","unit_id":"records-retention","prompt":{"en":"A fan sends many messages. How do you know whether they are also a high spender?","mk":"Фан испраќа многу пораки. Како да знаеш дали и троши многу?"},"options":[{"id":"a","en":"Assume every active fan spends a lot.","mk":"Претпостави дека секој активен фан троши многу."},{"id":"b","en":"Judge only by how long their replies are.","mk":"Процени само според должината на одговорите."},{"id":"c","en":"Count how many times they say hello.","mk":"Изброј колкупати се поздравуваат."},{"id":"d","en":"Check their purchase history rather than the number of messages.","mk":"Провери ја историјата на купување наместо бројот на пораки."}],"correct":"d","source_anchor":"A \"whale\" is a customer who spends significantly more money than an average subscriber.","explanation":{"en":"High spending is about purchases, not the number of messages a fan sends.","mk":"Големото трошење се однесува на купувањата, а не на бројот пораки што ги испраќа фанот."}}}]$questions$::jsonb) loop
  desired:=patch->'after';
  select to_jsonb(q) into current_record from evzon_private.exam_questions q where q.id=desired->>'id' for update;
  if current_record=desired then continue; end if;
  if current_record is null or md5(current_record::text) is distinct from patch->>'before_md5' then
   raise exception 'Question % changed since review; no changes made to this batch',desired->>'id';
  end if;
  if current_record->>'test_key' is distinct from desired->>'test_key' or current_record->>'correct' is distinct from desired->>'correct' then
   raise exception 'Question identity or answer-key mapping changed';
  end if;
  if not exists(select 1 from evzon_private.training_units u where u.id=desired->>'unit_id' and u.published and strpos(u.body,desired->>'source_anchor')>0) then
   raise exception 'Supporting guide changed for question %',desired->>'id';
  end if;
  update evzon_private.exam_questions set
   unit_id=desired->>'unit_id',prompt=desired->'prompt',options=desired->'options',
   source_anchor=desired->>'source_anchor',explanation=desired->'explanation'
  where id=desired->>'id';
  if not exists(select 1 from evzon_private.exam_questions q where q.id=desired->>'id' and to_jsonb(q)=desired) then
   raise exception 'Question verification failed';
  end if;
 end loop;
end $release$;
