 for patch in select value from jsonb_array_elements($questions$[{"before_md5":"d337150ba2020a6216fad538c20db093","after":{"id":"p5-21","test_key":"practice-5","unit_id":"shift-preparation","prompt":{"en":"You take over a chat from the previous shift. How should you begin your reply?","mk":"Преземаш разговор од претходната смена. Како треба да го започнеш одговорот?"},"options":[{"id":"a","en":"Continue from the previous conversation.","mk":"Продолжи од претходниот разговор."},{"id":"b","en":"Start over as though the customer has never messaged.","mk":"Почни одново како клиентот никогаш да не пишувал."},{"id":"c","en":"Ask all introductory questions again regardless of the notes.","mk":"Повторно постави ги сите воведни прашања без оглед на белешките."},{"id":"d","en":"Send an unrelated offer to establish a new topic.","mk":"Испрати неповрзана понуда за да воспоставиш нова тема."}],"correct":"a","source_anchor":"When responding to a customer, continue from the previous conversation.","explanation":{"en":"The guide says to continue naturally from earlier interactions instead of restarting from zero.","mk":"Водичот бара природно продолжување на претходните разговори наместо повторно почнување од нула."}}},{"before_md5":"a188496710ce72af17693995724d3a22","after":{"id":"p5-22","test_key":"practice-5","unit_id":"support-boundaries","prompt":{"en":"In EVZON’s guides, which platform does the AI-model section apply to?","mk":"Во водичите на EVZON, за која платформа важи делот за AI модели?"},"options":[{"id":"a","en":"OnlyFans only.","mk":"Само за OnlyFans."},{"id":"b","en":"Both platforms without any difference.","mk":"За двете платформи без никаква разлика."},{"id":"c","en":"Neither platform.","mk":"За ниту една платформа."},{"id":"d","en":"Fanvue only.","mk":"Само за Fanvue."}],"correct":"d","source_anchor":"**Fanvue only:** At EVZON, OnlyFans work is with real models. Around 90% of our Fanvue assignments are with AI models.","explanation":{"en":"The AI-model guidance is for Fanvue only. EVZON’s OnlyFans work is with real models.","mk":"Насоките за AI модели се само за Fanvue. Работата на EVZON на OnlyFans е со вистински модели."}}},{"before_md5":"0fe3619028e4b7bacd8be85522a56266","after":{"id":"p5-23","test_key":"practice-5","unit_id":"daily-checklist","prompt":{"en":"The inbox is quiet for a while. What useful task can you do?","mk":"Сандачето е мирно некое време. Која корисна задача можеш да ја направиш?"},"options":[{"id":"a","en":"Stop checking for new subscribers until activity increases.","mk":"Престани да проверуваш за нови претплатници додека активноста не се зголеми."},{"id":"b","en":"Leave customer notes unchanged until the next month.","mk":"Остави ги белешките за клиентите непроменети до следниот месец."},{"id":"c","en":"Review earlier customers and suitable occasional re-engagement opportunities.","mk":"Прегледај претходни клиенти и соодветни можности за повремено повторно контактирање."},{"id":"d","en":"Send the same new paid offer to every inactive subscriber.","mk":"Испрати ја истата нова платена понуда до секој неактивен претплатник."}],"correct":"c","source_anchor":"Contact inactive subscribers occasionally.","explanation":{"en":"The quiet-period checklist includes reviewing previous customers, appropriate re-engagement and occasional contact with inactive subscribers.","mk":"Листата за мирни периоди вклучува преглед на претходни клиенти, соодветно повторно вклучување и повремено контактирање неактивни претплатници."}}},{"before_md5":"a0e52d78c69f939697ff26b46ba5dbb0","after":{"id":"p5-24","test_key":"practice-5","unit_id":"infloww-shift","prompt":{"en":"You are leaving while a customer’s conversation is unfinished. What should you leave for the next chatter?","mk":"Заминуваш додека разговорот со клиентот е незавршен. Што треба да оставиш за следниот чатер?"},"options":[{"id":"a","en":"Remove the customer’s notes so the next shift starts fresh.","mk":"Отстрани ги белешките за клиентот за следната смена да почне одново."},{"id":"b","en":"Hand the conversation over properly with a note.","mk":"Предај го разговорот правилно, со белешка."},{"id":"c","en":"Leave the conversation without context for the next chatter.","mk":"Остави го разговорот без контекст за следниот четер."},{"id":"d","en":"Start a separate conversation and abandon the existing one.","mk":"Почни одделен разговор и напушти го постојниот."}],"correct":"b","source_anchor":"Hand over mid-deal conversations properly, with a note.","explanation":{"en":"The tool-etiquette section requires a note when handing over an unfinished deal.","mk":"Делот за правилно користење на алатките бара белешка при предавање незавршен договор."}}},{"before_md5":"3a8843914f29746262be83e081d629de","after":{"id":"p5-25","test_key":"practice-5","unit_id":"infloww-shift","prompt":{"en":"What should you do with unfinished drafts when logging out?","mk":"Што треба да направиш со незавршените нацрти при одјавување?"},"options":[{"id":"a","en":"Log out cleanly without leaving drafts.","mk":"Одјави се правилно без да оставаш нацрт-пораки."},{"id":"b","en":"Leave unfinished drafts for customers to interpret later.","mk":"Остави недовршени нацрти за клиентите подоцна да ги протолкуваат."},{"id":"c","en":"Keep the session open so nobody needs to sign in again.","mk":"Остави ја сесијата отворена за никој повторно да не се најавува."},{"id":"d","en":"Share your login so the next chatter can finish your drafts.","mk":"Сподели ги твоите податоци за најава за следниот четер да ги доврши нацртите."}],"correct":"a","source_anchor":"Log out cleanly, don't leave drafts.","explanation":{"en":"The guide’s tool etiquette explicitly says to log out cleanly and leave no drafts.","mk":"Правилата за користење на алатките изречно бараат правилно одјавување без оставање нацрт-пораки."}}}]$questions$::jsonb) loop
  desired:=patch->'after';
  select to_jsonb(q) into current_record from evzon_private.exam_questions q where q.id=desired->>'id' for update;
  if current_record=desired then continue; end if;
  if current_record is null or md5(current_record::text) is distinct from patch->>'before_md5' then
   raise exception 'Question % changed since review; no changes made to this batch',desired->>'id';
  end if;
  if current_record->>'test_key' is distinct from desired->>'test_key' or current_record->>'correct' is distinct from desired->>'correct' then
   raise exception 'Question identity or answer-key mapping changed';
  end if;
  if not exists(select 1 from evzon_private.training_units u where u.id=desired->>'unit_id' and u.published and strpos(u.body,desired->>'source_anchor')>0) then
   raise exception 'Supporting guide changed for question %',desired->>'id';
  end if;
  update evzon_private.exam_questions set
   unit_id=desired->>'unit_id',prompt=desired->'prompt',options=desired->'options',
   source_anchor=desired->>'source_anchor',explanation=desired->'explanation'
  where id=desired->>'id';
  if not exists(select 1 from evzon_private.exam_questions q where q.id=desired->>'id' and to_jsonb(q)=desired) then
   raise exception 'Question verification failed';
  end if;
 end loop;
end $release$;
commit;
select '31' as batch, count(*) as bank_questions from evzon_private.exam_questions;
